// Split clips array into individual items
const clips = $json.data.clips || [];

if (clips.length === 0) {
  throw new Error('No clips found — try a more descriptive query (4-6 words). Check: https://wayin.ai/api-docs/find-moments/');
}

return clips.map(clip => ({
  json: {
    title: clip.title || 'Onboarding Clip',
    export_link: clip.export_link || '',
    score: clip.score || 0,
    tags: Array.isArray(clip.tags) ? clip.tags : [],
    desc: clip.desc || '',
    begin_ms: clip.begin_ms || 0,
    end_ms: clip.end_ms || 0,
    idx: clip.idx || 0
  }
}));
